import React, { useState } from 'react';
import Dashboard from './components/Dashboard/Dashboard';
import Members from './components/Members/MemberList';
import Trainers from './components/Trainers/TrainerList';
import Classes from './components/Classes/ClassList';
import Payments from './components/Payments/PaymentList';
import Attendance from './components/Attendance/Attendance';
import Reports from './components/Reports/Reports';
import EmailNotifications from './components/Notifications/EmailNotifications';
import Logo from './components/Branding/Logo';
import Footer from './components/common/Footer';

function App() {
  const [currentPage, setCurrentPage] = useState('dashboard');

  const pages = {
    dashboard: <Dashboard />,
    members: <Members />,
    trainers: <Trainers />,
    classes: <Classes />,
    payments: <Payments />,
    attendance: <Attendance />,
    reports: <Reports />,
    email: <EmailNotifications />,
  };

  const navItems = [
    { id: 'dashboard', label: 'Dashboard', emoji: '📊' },
    { id: 'members', label: 'Members', emoji: '👥' },
    { id: 'trainers', label: 'Trainers', emoji: '🏋️' },
    { id: 'classes', label: 'Classes', emoji: '📅' },
    { id: 'payments', label: 'Payments', emoji: '💳' },
    { id: 'attendance', label: 'Attendance', emoji: '✅' },
    { id: 'reports', label: 'Reports', emoji: '📊' },
    { id: 'email', label: 'Email', emoji: '📧' },
  ];

  return (
    <div style={{
      fontFamily: 'Segoe UI, Arial, sans-serif',
      padding: '20px',
      maxWidth: '1200px',
      margin: '0 auto',
      background: '#f4f7fc',
      minHeight: '100vh'
    }}>
      {/* Header */}
      <div style={{
        background: 'white',
        padding: '15px 30px',
        borderRadius: '12px',
        boxShadow: '0 2px 8px rgba(0,0,0,0.08)',
        marginBottom: '20px',
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'space-between'
      }}>
        <Logo size="medium" />
        <div style={{ fontSize: '14px', color: '#6b7a8d' }}>
          {new Date().toLocaleDateString('en-US', {
            weekday: 'long',
            year: 'numeric',
            month: 'long',
            day: 'numeric'
          })}
        </div>
      </div>

      {/* Navigation */}
      <nav style={{
        display: 'flex',
        gap: '8px',
        marginBottom: '20px',
        background: 'white',
        padding: '10px 20px',
        borderRadius: '12px',
        boxShadow: '0 2px 8px rgba(0,0,0,0.08)',
        flexWrap: 'wrap'
      }}>
        {navItems.map((item) => (
          <button
            key={item.id}
            onClick={() => setCurrentPage(item.id)}
            style={{
              padding: '10px 20px',
              background: currentPage === item.id ? '#2c3e50' : 'transparent',
              color: currentPage === item.id ? 'white' : '#2c3e50',
              border: 'none',
              borderRadius: '8px',
              cursor: 'pointer',
              fontSize: '15px',
              fontWeight: currentPage === item.id ? '600' : '400',
              transition: 'all 0.3s',
              display: 'flex',
              alignItems: 'center',
              gap: '8px',
            }}
          >
            <span>{item.emoji}</span>
            {item.label}
          </button>
        ))}
      </nav>

      {/* Page Content */}
      <div style={{
        padding: '24px',
        background: 'white',
        borderRadius: '12px',
        boxShadow: '0 2px 8px rgba(0,0,0,0.08)',
        minHeight: '400px'
      }}>
        {pages[currentPage] || pages.dashboard}
      </div>

      {/* Footer */}
      <Footer />
    </div>
  );
}

export default App;
